static int Main(string[] args){try{
var original=BloodmoonLog.Parse(File.ReadAllText(args[0]));var bytes=StatisticsWire.Encode(original);var decoded=StatisticsWire.Decode(bytes);Need(decoded.Nights[0].Total==385&&decoded.Nights[1].Total==274,"fixture totals");Need(!decoded.Nights[0].Kills.ContainsKey("Player5")&&decoded.Nights[1].Kills["Player2"]==0,"missing versus zero");Reject(()=>StatisticsWire.Decode(bytes.Concat(new byte[]{0}).ToArray()));Reject(()=>StatisticsWire.Decode(new byte[]{2,0,0}));Reject(()=>StatisticsWire.Decode(bytes.Take(bytes.Length-1).ToArray()));
