string root=args[1];Directory.CreateDirectory(Path.Combine(root,"Data"));File.Copy(args[0],Path.Combine(root,"Data","bloodmoon_kills.txt"),true);StatisticsSync.Initialize(root);GameManager.Instance.World=new World();ConnectionManager.Instance.IsServer=true;var client=new ClientInfo{entityId=1};ConnectionManager.Instance.Clients.Client=client;StatisticsSync.Tick();int roleReads=ConnectionManager.Instance.RoleReads;for(int i=0;i<100;i++)StatisticsSync.Tick();Need(ConnectionManager.Instance.RoleReads==roleReads,"role cached across updates");StatisticsSync.HandleRequest(new ClientInfo{entityId=1},1,new byte[32]);Need(client.Sent.Count==0,"unregistered sender");StatisticsSync.HandleRequest(client,1,new byte[32]);Need(client.Sent.Count>0,"server reply");var replies=client.Sent.ToArray();StatisticsSync.HandleRequest(client,2,new byte[32]);Need(client.Sent.Count==replies.Length,"rate limit");
GameManager.Instance.World=new World();ConnectionManager.Instance.IsServer=false;File.WriteAllText(Path.Combine(root,"Data","bloodmoon_kills.txt"),"invalid client local file");StatisticsSync.Request();Need(StatisticsSync.Snapshot().Data==null&&StatisticsSync.Snapshot().Busy,"client waits instead of reading local");foreach(var reply in replies){using(var r=new PooledBinaryReader(new MemoryStream(reply))){r.ReadUInt16();var package=new NetPackageStatisticsReply();package.read(r);package.ProcessPackage(null,null);}}var cached=StatisticsSync.Snapshot().Data;Need(cached.Nights[0].Total==385&&!StatisticsSync.Snapshot().Busy,"game package roundtrip");StatisticsSync.Request();StatisticsSync.HandleReply(2,1,0,0,0,StatisticsWire.Hash(bytes),new byte[0]);Need(Object.ReferenceEquals(cached,StatisticsSync.Snapshot().Data),"unchanged cache");StatisticsSync.Request();StatisticsSync.HandleReply(3,0,0,1,bytes.Length,new byte[32],bytes);Need(Object.ReferenceEquals(cached,StatisticsSync.Snapshot().Data)&&StatisticsSync.Snapshot().Error!=null,"corruption retains valid cache");StatisticsSync.Request();UnityEngine.Time.unscaledTime=11;StatisticsSync.Tick();Need(!StatisticsSync.Snapshot().Busy&&StatisticsSync.Snapshot().Error!=null,"timeout");GameManager.Instance.World=new World();Need(StatisticsSync.Snapshot().Data==null,"world change clears cache");Need(ConnectionManager.Instance.RoleReads==roleReads+2,"role refreshed once per world");string liveRoot=Path.Combine(root,"live-"+Guid.NewGuid().ToString("N"));StatisticsSync.Initialize(liveRoot);ConnectionManager.Instance.IsServer=true;var liveWorld=new World{Now=6UL*24000+21999};var livePlayer=new EntityPlayer{entityId=1,EntityName="Player",Kills=100};liveWorld.Players.list.Add(livePlayer);GameManager.Instance.World=liveWorld;UnityEngine.Time.unscaledTime=20;StatisticsSync.Tick();Need(livePlayer.Reads==0,"no counters before bloodmoon");liveWorld.Now++;UnityEngine.Time.unscaledTime=20.1f;StatisticsSync.Tick();Need(livePlayer.Reads==1&&BloodmoonRecording.LiveNight.Kills["Player"]==0,"start and live zero");livePlayer.Kills=103;for(int j=2;j<=9;j++){liveWorld.Now++;UnityEngine.Time.unscaledTime=20+j/10f;StatisticsSync.Tick();}Need(livePlayer.Reads==1,"less than one second no resample");liveWorld.Now++;UnityEngine.Time.unscaledTime=21.2f;StatisticsSync.Tick();Need(livePlayer.Reads==2&&StatisticsSync.Snapshot().Data.Nights[0].Kills["Player"]==3,"one-second sample and live table");liveWorld.Now=7UL*24000+4000;UnityEngine.Time.unscaledTime=23;StatisticsSync.Tick();Need(BloodmoonRecording.LiveNight==null&&StatisticsSync.Snapshot().Data.Nights[0].Kills["Player"]==3,"live hidden and finished table preserved");
Console.WriteLine("PASS: fixture, multipart, duplicates, corruption, trusted sender, rate limit, package roundtrip, remote file isolation, cache, timeout, world change.");return 0;
